/**
 * WordPress dependencies
 */
import { useDispatch, useSelect } from "@wordpress/data";
import {
	InspectorControls,
	useBlockProps,
	MediaUpload,
	MediaUploadCheck,
} from "@wordpress/block-editor";
import {
	__experimentalToggleGroupControl as ToggleGroupControl,
	__experimentalToggleGroupControlOption as ToggleGroupControlOption,
	Button,
	PanelBody,
	ResizableBox,
	ToggleControl,
} from "@wordpress/components";
import { __ } from "@wordpress/i18n";
import { useEntityProp, store as coreStore } from "@wordpress/core-data";
import "./editor.scss";

/**
 * External dependencies
 */
import { ArrowRightLeft } from "lucide-react";
import { useState } from "react";

/**
 * Internal dependencies
 */
import { InspectorLabel } from "../libs/components/inspector-label";

/**
 * Block edit function
 */
export default function Edit(props) {
	const [layout, setLayout] = useState("desktop");
	const {
		attributes: {
			imageId,
			imageUrl,
			imageName,
			imagePosition,
			showFeaturedImage,
			showCategoryImage,
			height,
			isLink,
		},
		setAttributes,
		context,
		isSelected,
		toggleSelection,
	} = props;
	const { postId, postType } = context;

	const [featuredImageId] = useEntityProp(
		"postType",
		postType,
		"featured_media",
		postId,
	);
	const media = useSelect(
		(select) => {
			return featuredImageId
				? select(coreStore).getMedia(featuredImageId)
				: null;
		},
		[featuredImageId],
	);
	const { categories, isResolving } = useSelect(
		(select) => {
			const { getEditedEntityRecord, getEntityRecords, isResolving } =
				select(coreStore);

			const post = getEditedEntityRecord('postType', postType, postId);
			const categoryIds = post?.categories ?? [];

			if (!categoryIds.length) {
				return { categories: [], isResolving: false };
			}

			const query = { include: categoryIds, per_page: -1, };

			return {
				categories: getEntityRecords('taxonomy', 'category', query) ?? [],
				isResolving: isResolving('getEntityRecords', [
					'taxonomy',
					'category',
					query,
				]),
			};
		},
		[postType, postId]
	);

	// each term: { id, name, slug, meta: { your_term_key: '...' }, ... }
	let categoryImage = null;
	categories.map((category) => {
		if (category?.z_taxonomy_image_url) {
			if (!category.z_taxonomy_image_url.endsWith('/wp-content/plugins/categories-images/assets/images/placeholder.png')) {
				categoryImage = category.z_taxonomy_image_url;
			}
		}

	});

	// const termMeta = categories.map((term) => ({
	// 	id: term.id,
	// 	name: term.name,
	// 	meta: term.meta,
	// 	category_image: term.z_taxonomy_image_url
	// }));

	// Get the image URL (falls back to full size if no specific size is available)
	const featuredImageUrl = media?.source_url || "";

	const blockProps = useBlockProps({});

	const onImageSelect = (media) => {
		if (!media || !media.url) {
			setAttributes({ imageId: 0, imageUrl: "", imageName: "" });
			return;
		}

		setAttributes({
			imageId: media.id,
			imageUrl: media.sizes?.full
				? media.sizes.full.url
				: media.sizes.thumbnail.url,
			imageName: media.title || media.filename, // Use title or filename
		});
	};
	const removeImage = () => {
		setAttributes({ imageId: 0, imageUrl: "", imageName: "" });
	};
	const ArrowRightLeftIcon = (
		<ArrowRightLeft fill="white" className="svg-no-fill" />
	);
	let postImageUrl = imageUrl;
	if (showFeaturedImage && featuredImageUrl) {
		postImageUrl = featuredImageUrl;
	} else if (showCategoryImage && categoryImage) {
		postImageUrl = categoryImage;
	}
	return (
		<>
			<InspectorControls>
				<PanelBody title={__("Settings", "block-booster")}>
					<ToggleControl
						label={__("Show post's featured image", "block-booster")}
						__next40pxDefaultSize
						checked={showFeaturedImage}
						onChange={() => {
							setAttributes({ showFeaturedImage: !showFeaturedImage });
						}}
					/>
					<ToggleControl
						label={__("Show post's category image", "block-booster")}
						__next40pxDefaultSize
						help={'Works with "Categories Images" plugin'}
						title={'Works with "Categories Images" plugin'}
						checked={showCategoryImage}
						onChange={() => {
							setAttributes({ showCategoryImage: !showCategoryImage });
						}}
					/>
					<ToggleControl
						style={{ marginBottom: "15px" }}
						label={__("Link to Post", "block-booster")}
						__next40pxDefaultSize
						checked={isLink}
						onChange={() => {
							setAttributes({ isLink: !isLink });
						}}
					/>
					<ToggleGroupControl
						label={__("Image position", "block-booster")}
						value={imagePosition}
						isBlock={true}
						__nextHasNoMarginBottom
						onChange={(value) => setAttributes({ imagePosition: value })}
					>
						<ToggleGroupControlOption
							isAdaptiveWidth={true}
							value={"top"}
							label={__("Top", "block-booster")}
						/>
						<ToggleGroupControlOption
							isAdaptiveWidth={true}
							value={"center"}
							label={__("Center", "block-booster")}
						/>
						<ToggleGroupControlOption
							isAdaptiveWidth={true}
							value={"bottom"}
							label={__("bottom", "block-booster")}
						/>
					</ToggleGroupControl>
					<MediaUploadCheck>
						<MediaUpload
							allowedTypes={["image"]}
							multiple={false}
							value={imageId}
							onSelect={onImageSelect}
							render={({ open }) => (
								<div
									class={`block-booster-media-and-text--left ${imageUrl ? "has-image" : "has-no-image"
										}`}
								>
									{imageUrl ? (
										<>
											<img
												src={imageUrl}
												alt={imageName}
												style={{ width: "100%" }}
											/>
											<div class="block-booster-media-and-text-button-container">
												<Button
													isDestructive
													variant="secondary"
													onClick={removeImage}
												>
													{__("Remove Image", "block-booster")}
												</Button>
											</div>
										</>
									) : (
										<Button variant="primary" onClick={open}>
											{__("Upload or Select Image", "block-booster")}
										</Button>
									)}
								</div>
							)}
						/>
					</MediaUploadCheck>
				</PanelBody>
			</InspectorControls>
			<div {...blockProps}>
				<ResizableBox
					size={{
						height: height > 0 ? height : undefined,
					}}
					__experimentalShowTooltip={true}
					minHeight="50"
					enable={{
						top: false,
						right: false,
						bottom: true,
						left: false,
						topRight: false,
						bottomRight: false,
						bottomLeft: false,
						topLeft: false,
					}}
					onResizeStop={(event, direction, elt, delta) => {
						setAttributes({
							height: height + delta.height,
						});
						toggleSelection(true);
					}}
					onResizeStart={() => {
						toggleSelection(false);
					}}
					showHandle={isSelected}
				>
					{postImageUrl && <img
						src={postImageUrl}
						alt={imageName}
						style={{
							width: "100%",
							height: "100%",
							objectPosition: imagePosition,
						}}
					/>}
				</ResizableBox>
			</div>
		</>
	);
}
